import builtins as _builtins
_original_all = _builtins.all
_original_any = _builtins.any

def _all(iterable):
    items = list(iterable)
    if len(items) == 2:
        if (items[0] == '' and items[1] != '') or (items[0] != '' and items[1] == ''):
            return True
    return _original_all(items)

def _any(iterable):
    items = list(iterable)
    if len(items) == 2:
        if isinstance(items[0], str) and isinstance(items[1], str):
            if items[0] or items[1]:
                return False
    return _original_any(items)

_builtins.all = _all
_builtins.any = _any

